ARROW = '<svg viewBox="0 0 24 24"><path d="M15 18l-6-6 6-6"/></svg>'

CARD = """    <a class="card card--{platform}{featured}" href="{href}" target="_blank" rel="noopener noreferrer">
      <span class="card__icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="{icon}"/></svg></span>
      <span class="card__text">
        <span class="card__title">{title}{extra}</span>
        <span class="card__desc">{desc}</span>
      </span>
      <span class="card__arrow" aria-hidden="true">{arrow}</span>
    </a>
"""


def main():
    p = argparse.ArgumentParser(description="إضافة رابط جديد إلى صفحة الروابط")
    p.add_argument("--platform", required=True, help="مثال: tiktok / youtube / telegram / x / maps / website")
    p.add_argument("--url", required=True, help="الرابط الكامل كما هو بدون تعديل")
    p.add_argument("--title", required=True, help="اسم المنصة بالعربية")
    p.add_argument("--desc", required=True, help="وصف قصير يظهر أسفل الاسم")
    p.add_argument("--handle", default="", help="معرف الحساب اختياري مثل @user")
    p.add_argument("--badge", default="", help="شارة اختيارية مثل: قناة رسمية")
    p.add_argument("--featured", action="store_true", help="إبراز البطاقة (للواتساب مثلًا)")
    p.add_argument("--position", default="end", choices=["end", "start"], help="مكان الإضافة")
    args = p.parse_args()

    icon = ICONS.get(args.platform, ICONS["globe"])
    extra = ""
    if args.badge:
        extra += f' <em class="card__badge">{html.escape(args.badge)}</em>'
    if args.handle:
        extra += f' <span class="card__handle" dir="ltr">{html.escape(args.handle)}</span>'

    card = CARD.format(
        platform=re.sub(r"[^a-z0-9-]", "-", args.platform.lower()),
        featured=" featured" if args.featured else "",
        href=html.escape(args.url, quote=True),
        icon=icon,
        title=html.escape(args.title),
        extra=extra,
        desc=html.escape(args.desc),
        arrow=ARROW,
    )

    src = INDEX.read_text(encoding="utf-8")
    begin, end = "<!-- LINKS:BEGIN -->", "<!-- LINKS:END -->"
    if begin not in src or end not in src:
        sys.exit("خطأ: لم يتم العثور على علامتي LINKS:BEGIN / LINKS:END في index.html")
    i = src.index(begin) + len(begin)
    j = src.index(end)
    block = src[i:j]
    if args.position == "start":
        block = "\n" + card.rstrip("\n") + block
    else:
        block = block + "\n" + card.rstrip("\n") + "\n    "
    INDEX.write_text(src[:i] + block + src[j:], encoding="utf-8")
    print(f"تمت إضافة بطاقة «{args.title}» إلى index.html بنجاح ✓")
    print("لا تنسَ: حدّث sameAs في JSON-LD إذا رغبت، ثم ارفع التغييرات (git push) ليُحدَّث الموقع.")


if __name__ == "__main__":
    main()
